import { beforeEach,describe,expect,it } from 'vitest';import { AvailityConnector } from '../../clearinghouses/availity.connector';import { X12GeneratorService } from '../../x12/x12-generator.service';import { X12ParserService } from '../../x12/x12-parser.service';
describe('AvailityConnector synthetic X12 parity',()=>{let c:AvailityConnector;beforeEach(async()=>{const g=new X12GeneratorService();c=new AvailityConnector({} as any,{record:async()=>{}} as any,{baseUrl:'https://x12.test',tenantId:'t',clientId:'c'},g,new X12ParserService(g));await c.authorize('s')});it('covers 270/271 837P 276/277 835 without transmission',async()=>{const e=await c.checkEligibility270('S');expect(e.x12Response).toContain('*ST*271*0');const cl=await c.submitClaim837P({patientMemberId:'S',cptCode:'90837',icd10Codes:['F32.9'],billedAmount:100,serviceDate:new Date('2026-01-01')});expect(cl.x12).toContain('*ST*837P*0');const st=await c.checkClaimStatus276(cl.claimId,'S');expect(st.x12Response).toContain('*ST*277*0');const era=await c.postEra835(cl.claimId,100);expect(era.x12).toContain('*ST*835*0');});it('caps synthetic sync at requested limit',async()=>{expect((await c.syncSyntheticResources('claims',1)).synced).toBe(1)})});
